import{_ as r,o as a,c as i,ag as t}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Release","description":"","frontmatter":{},"headers":[],"relativePath":"release/index.md","filePath":"release/index.md"}'),o={name:"release/index.md"};function d(n,e,s,c,l,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="release" tabindex="-1">Release <a class="header-anchor" href="#release" aria-label="Permalink to &quot;Release&quot;">​</a></h1><h2 id="published-provider-history-and-provider-4-candidate" tabindex="-1">Published Provider history and Provider 4 candidate <a class="header-anchor" href="#published-provider-history-and-provider-4-candidate" aria-label="Permalink to &quot;Published Provider history and Provider 4 candidate&quot;">​</a></h2><p>Provider <strong>v3.0.0</strong> is the current Registry-published Terraform/OpenTofu Provider. Its immutable release registers 31 typed resources across eight versionless families; each resource keeps an exact FormRef and provider mapping in its release identity projection. Provider release, Form Definition publication, package publication, and Host deployment are separate owner actions.</p><p>Provider <strong>v4.0.0</strong> is the candidate at the same <code>tako0614/takoform</code> address and selects only the 16 exact Edge Forms selected from the <code>tako0614/takoform-forms</code> publication. It does not claim that Provider 4 has been tagged or published. The 15 removed aggregate types and explicit state paths are documented in <a href="./migrations/v3-to-v4.html">v3 to v4 publisher-set migration</a>. Ordinary AWS, Cloudflare, Kubernetes, and other resources remain native resources of their own providers.</p><p>The unpublished candidate is described by <code>release/candidates/provider-v4.0.0.json</code>, with its derived 17-Form mapping in <code>release/candidates/provider-v4.0.0-form-identities.json</code>. The retired Provider 3 writer input and identity ledger remain byte-stable history; neither is reused to publish Provider 4.</p><p>The Provider 4 production binary embeds only that publisher closure: 16 Form Packages, their seven exact Interface definitions, and six exact Binding definitions. The complete Provider 3 artifact projection remains tracked as source-side immutable history for goldens and migration verification; it is no longer bundled into the current provider binary.</p><p>The signed release-tag commit must be an ancestor of the reviewed protected-main/readback commit used for the release.</p><p>The release identity and Registry readback are recorded in the <a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/release/provider-release-identities.json" target="_blank" rel="noreferrer">Provider release identity ledger</a>. The <a href="./../docs/">Provider reference</a> contains the install pin and generated resource contracts.</p><h2 id="compatibility-and-migration" tabindex="-1">Compatibility and migration <a class="header-anchor" href="#compatibility-and-migration" aria-label="Permalink to &quot;Compatibility and migration&quot;">​</a></h2><h3 id="retained-v1beta1-history-provider-2-1-1" tabindex="-1">Retained v1beta1 history (Provider 2.1.1) <a class="header-anchor" href="#retained-v1beta1-history-provider-2-1-1" aria-label="Permalink to &quot;Retained v1beta1 history (Provider 2.1.1)&quot;">​</a></h3><p>Provider 2.1.1 remains the compatibility predecessor. Its identity ledger retains 15 exact v1beta1 Form identities; 14 remain readable by Provider 3 state/import dispatch. ObjectBucket has no Provider 3 resource or codec, so ObjectBucket state needs explicit pre-upgrade handling. Existing Provider 2 state needs an explicit cutover; follow <a href="./migrations/v2-to-v3.html">v2 to v3 migration</a> before changing the required provider version. Provider 3 does not rewrite Provider 1 state; the <a href="./migrations/v1-to-v2.html">v1 to v2 migration</a> is the earlier boundary.</p><p>The Provider 4 publisher mapping group is <code>edge.forms.takoform.com</code> and uses <code>packages.forms.takoform.com/v1alpha5</code>. Retained Provider 2.1.1 history uses Host API <code>forms.takoform.com/v1beta1</code>, family <code>edge.forms.takoform.com/v1beta1</code>, and package envelope <code>packages.forms.takoform.com/v1alpha4</code>.</p><p>The <a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/website/docs/versions.md" target="_blank" rel="noreferrer">versions page</a> lists the current API/Core checkpoint, Provider releases, package publication, and retained history in one place.</p><h2 id="core-and-specification-history" tabindex="-1">Core and Specification history <a class="header-anchor" href="#core-and-specification-history" aria-label="Permalink to &quot;Core and Specification history&quot;">​</a></h2><p>The current Core/API checkpoint is <a href="https://github.com/tako0614/takoform/tree/v1.0.1/spec" target="_blank" rel="noreferrer">Core v1.0.1</a> on <code>forms.takoform.com/v1</code>. Specification 1.1 is retained as an immutable historical source receipt.</p><p>Release tooling and ledgers are maintained in the <a href="https://github.com/tako0614/terraform-provider-takoform/tree/main/release" target="_blank" rel="noreferrer">Provider repository</a>. They provide Provider provenance and migration evidence.</p>',16)])])}const v=r(o,[["render",d]]);export{m as __pageData,v as default};
